struct Base {
    void func(int) {}
    void func(double) {}
};
struct Derived : Base {};

// 1. Overload Resolution requires explicit target signature
void (Base::*p_int)(int) = &Base::func;
void (Base::*p_dbl)(double) = &Base::func;

// Ambiguity if target signature is omitted (must resolve):
// auto p_fail = &Base::func; // Error

// 2. Conversion Rule (Covariance for Member Pointers)
// Base::* can implicitly convert to Derived::*
void (Derived::*p_d_int)(int) = p_int; // Valid conversion
// Derived::* cannot implicitly convert to Base::* (Contravariance invalid)
// void (Base::*p_b_fail)(int) = p_d_int; // Error
